import {questions,parties,sources,rank} from './data.js';
const root=document.querySelector('#app');let answers=Array(18).fill(null),index=0,view='quiz',pinned=null,d3=null;
const label=a=>a===1?'Agree':a===-1?'Disagree':a===0?'Don’t care':'Unanswered';
const count=()=>answers.filter(a=>a!==null).length;
const brand=`<header><div class="brand"><span class="logo" aria-hidden="true">✓</span>common ground<span style="font-size:12px;font-weight:500;letter-spacing:0;color:#718177;margin-left:8px">/ 18</span></div><span class="edition">GERMANY · POLITICAL PERSPECTIVES</span><button class="text-button" id="about">How it works</button></header>`;
const footer=`<footer><span>Independent exploration. No affiliation with Wahl-O-Mat or any party.</span><span>Your answers stay in this page. No account. No tracking.</span></footer>`;
function method(){return `<details class="method" id="method"><summary>About the questions & scoring</summary><p>This is an independent, illustrative comparison of seven parties, based mainly on their 2025 federal election programmes. These 18 statements and party scores are editorial interpretations, not answers authorised by the parties. They are not a validated replacement for an official election questionnaire. State programmes and subsequent policy changes can differ.</p><p>Agree and disagree count equally: a full match earns 1 point, an opposite answer 0, and a mixed party position 0.5. Qualified positions may earn 0.25 or 0.75. “Don’t care” is excluded entirely, not counted as neutrality. Unknown party positions are also excluded, and the number compared is shown. Percentages are rounded; ties are equal compatibility. The graph shows only parties whose position leans in the direction of your answer; dashed lines indicate partial alignment.</p><p>Some questions were narrowed to avoid combining different policies: pensions concerns invested funds, privacy concerns indiscriminate metadata retention, and social values concerns adults’ legal gender records. Union’s investment-borrowing position is marked mixed because its 2025 programme and subsequent borrowing decisions differ. BSW’s nuclear position is left unknown rather than inferred.</p><div>${sources.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${n} programme ↗</a>`).join('')}</div><p><a href="https://www.tagesschau.de/inland/bundestagswahl/programmvergleich" target="_blank" rel="noopener noreferrer">Cross-party programme comparison ↗</a></p></details>`}
function render(){root.innerHTML=brand+`<main class="shell">${view==='quiz'?quiz():results()}</main>`+footer;document.querySelector('#about').onclick=()=>{const m=document.querySelector('#method');m.open=true;m.scrollIntoView({behavior:'smooth',block:'center'})};if(view==='quiz')bindQuiz();else bindResults()}
function quiz(){const q=questions[index];return `<div class="intro"><div><div class="eyebrow">Your perspective, one choice at a time</div><h1>Where do you stand?</h1><p class="muted">Consider both sides. Choose what feels right to you.</p></div><div class="step-label"><strong>${String(index+1).padStart(2,'0')}</strong> <span class="muted">/ 18</span></div></div><div class="quiz-layout"><aside class="sidebar"><h3>The 18 questions</h3><nav class="topics" aria-label="Questions">${questions.map((q,i)=>`<button class="topic ${i===index?'active':''} ${answers[i]!==null?'done':''}" data-index="${i}" aria-label="Question ${i+1}: ${q.topic}, ${label(answers[i])}" ${i===index?'aria-current="step"':''}><span class="n">${answers[i]!==null&&i!==index?'✓':String(i+1).padStart(2,'0')}</span><span class="topic-name">${q.topic}</span></button>`).join('')}</nav></aside><div><section class="card"><div class="progress" role="progressbar" aria-label="Questions answered" aria-valuenow="${count()}" aria-valuemin="0" aria-valuemax="18"><div style="width:${count()/18*100}%"></div></div><div class="question"><div class="question-top"><span class="eyebrow">Statement ${String(q.id).padStart(2,'0')}</span><span class="tag">${q.category}</span></div><h2 id="question-title" tabindex="-1">${q.statement}</h2><div class="argument-grid"><div class="argument"><h3><span class="sign">+</span>The case for</h3><p>${q.pro}</p></div><div class="argument con"><h3><span class="sign">−</span>The case against</h3><p>${q.con}</p></div></div><div class="answers" role="group" aria-labelledby="question-title">${[[1,'✓','Agree'],[-1,'×','Disagree'],[0,'—','Don’t care']].map(([v,s,l])=>`<button class="answer ${answers[index]===v?'selected':''}" data-answer="${v}" aria-pressed="${answers[index]===v}"><span aria-hidden="true">${s}</span>${l}</button>`).join('')}</div><div class="navrow"><button class="text-button" id="back" ${index===0?'disabled':''}>← Back</button><span class="hint">${count()} of 18 answered</span><button class="primary" id="next" ${answers[index]===null?'disabled':''}>${count()===18?'See my results':index===17?'Finish unanswered':'Next question'} →</button></div></div></section><p class="bottom-note">No right answers. “Don’t care” leaves a topic out of your match.</p></div></div>${method()}`}
function bindQuiz(){document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>{index=+b.dataset.index;render();focusQuestion()});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[index]=+b.dataset.answer;render();document.querySelector(`[data-answer="${answers[index]}"]`).focus()});document.querySelector('#back').onclick=()=>{index--;render();focusQuestion()};document.querySelector('#next').onclick=()=>{if(answers[index]===null)return;if(count()===18)view='results';else index=index===17?answers.indexOf(null):index+1;render();if(view==='quiz')focusQuestion();else window.scrollTo({top:0,behavior:'smooth'})}}
function focusQuestion(){document.querySelector('#question-title')?.focus({preventScroll:true})}
function results(){const ranked=rank(answers),answered=answers.filter(a=>a!==0&&a!==null).length;return `<div class="result-head"><div class="kicker"><span class="eyebrow">Your results</span><span class="pill">${answered} topics counted</span></div><h1>Your political common ground.</h1><p class="muted">See the overall picture. Then follow the connections behind it.</p></div>${answered?`<div class="results-grid"><section class="card rankings"><h2>Your alignment</h2><p class="muted">Across the statements you care about.</p>${ranked.map((r,i)=>{const p=parties[r.party];return `<div class="rank-item" style="--party:${p[2]}"><div class="rank-line"><span class="swatch"></span><strong>${p[0]}</strong><span class="percent">${r.score===null?'—':r.score+'%'}</span></div><div class="bar"><span style="width:${r.score??0}%"></span></div><span class="coverage">${r.count} of ${answered} topics compared</span></div>`}).join('')}</section><section class="card graph-card"><div class="graph-top"><div><h2>Follow your answers</h2><p class="muted">Hover, focus or tap a topic to trace its connections.</p></div><div class="graph-legend">── Full &nbsp; ╌ Partial</div></div><div class="graph-wrap"><svg class="network" viewBox="0 0 640 680" aria-label="Connections between your answers and party positions"></svg></div><div class="graph-detail" aria-live="polite">Select a topic to explore where your answer aligns.</div></section></div>`:`<section class="card all-skipped"><h2>No positions to compare yet.</h2><p class="muted">You chose “Don’t care” for every topic, so there is no meaningful ranking. Give at least one statement an agree or disagree answer to see your connections.</p></section>`}<div class="result-actions"><button class="primary" id="review">Review my answers</button><button class="text-button" id="restart">Start again</button></div><details class="method"><summary>Your 18 answers</summary><div class="statement-review">${questions.map((q,i)=>`<div class="review-row"><span>${i+1}. ${q.statement}</span><button data-edit="${i}">${label(answers[i])} ↗</button></div>`).join('')}</div></details>${method()}`}
function bindResults(){document.querySelector('#review').onclick=()=>{view='quiz';index=0;render()};document.querySelector('#restart').onclick=()=>{answers=Array(18).fill(null);view='quiz';index=0;pinned=null;render()};document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{view='quiz';index=+b.dataset.edit;render();focusQuestion()});if(document.querySelector('.network'))drawGraph()}
async function drawGraph(){if(!d3){try{d3=await import('./vendor/d3-shape.js')}catch{document.querySelector('.graph-detail').textContent='The connection view could not load. Your ranking and answer review are still available.';return}}if(view!=='results')return;const svg=document.querySelector('.network');if(!svg)return;const link=d3.linkHorizontal();const edges=[];questions.forEach((q,i)=>parties.forEach((p,j)=>{if(answers[i]&&q.positions[j]!==null&&answers[i]*q.positions[j]>0)edges.push({i,j,partial:Math.abs(q.positions[j])<1})}));svg.innerHTML=`<text x="12" y="26" fill="#829087" font-size="11" letter-spacing="1.5">YOUR ANSWERS</text><text x="497" y="26" fill="#829087" font-size="11" letter-spacing="1.5">PARTIES</text><g>${edges.map(e=>`<path class="edge" data-q="${e.i}" data-p="${e.j}" ${e.partial?'stroke-dasharray="5 4"':''} d="${link({source:[215,58+e.i*34],target:[485, ninety(e.j)]})}"/>`).join('')}</g>${questions.map((q,i)=>`<g class="node" tabindex="0" role="button" aria-label="${q.topic}: ${label(answers[i])}. Show aligned parties" data-node="${i}" transform="translate(0 ${58+i*34})"><rect x="0" y="-16" width="233" height="32" fill="transparent"/><text x="12" y="5">${String(i+1).padStart(2,'0')} &nbsp; ${q.topic}</text><circle cx="215" r="5"/></g>`).join('')}${parties.map((p,j)=>`<g class="party-node" transform="translate(485 ${ninety(j)})"><circle r="6" fill="${p[2]}"/><text x="16" y="5" fill="${p[2]}">${p[0]}</text></g>`).join('')}`;svg.querySelectorAll('[data-node]').forEach(n=>{let i=+n.dataset.node;n.onmouseenter=()=>highlight(i);n.onmouseleave=()=>highlight(pinned);n.onfocus=()=>highlight(i);n.onblur=()=>highlight(pinned);n.onclick=()=>{pinned=pinned===i?null:i;highlight(pinned)};n.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();n.onclick()}if(e.key==='Escape'){pinned=null;highlight(null)}}});highlight(pinned)}
function ninety(j){return  ninetyBase+j*85}const ninetyBase=90;
function highlight(i){document.querySelectorAll('.edge').forEach(p=>{let active=+p.dataset.q===i;p.classList.toggle('lit',active);p.style.stroke=active?parties[+p.dataset.p][2]:'';p.style.opacity=i===null?'':active?'.9':'.07'});document.querySelectorAll('[data-node]').forEach(n=>n.classList.toggle('active',+n.dataset.node===i));const el=document.querySelector('.graph-detail');if(!el)return;if(i===null){el.innerHTML='Select a topic to explore where your answer aligns.<p>Connections reflect your answer, including when you disagree.</p>';return}const q=questions[i],matches=parties.filter((p,j)=>answers[i]&&q.positions[j]!==null&&answers[i]*q.positions[j]>0).map(p=>p[0]);el.innerHTML=`<strong>${String(i+1).padStart(2,'0')} · ${q.topic}</strong> <span class="muted">— You chose ${label(answers[i]).toLowerCase()}</span><p>${q.statement}</p><span>${answers[i]===0?'Excluded from scoring. No alignment is implied.':matches.length?'Aligned: '+matches.join(', '):'No party clearly aligns on this statement.'}</span>`}
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'answer_political_questions',description:'Set answers to one or more of the 18 questions. Does not open results automatically.',inputSchema:{type:'object',properties:{answers:{type:'array',items:{type:'object',properties:{question:{type:'integer',minimum:1,maximum:18},answer:{type:'integer',enum:[-1,0,1]}},required:['question','answer'],additionalProperties:false}}},required:['answers'],additionalProperties:false},execute(input){if(!input||!Array.isArray(input.answers)||input.answers.some(a=>!Number.isInteger(a.question)||a.question<1||a.question>18||![-1,0,1].includes(a.answer)))throw new Error('Use question 1–18 and answer -1, 0 or 1.');input.answers.forEach(a=>answers[a.question-1]=a.answer);render();return {answered:count(),total:18}}})).catch(()=>{})}catch{}}
